-- Optional: table + seed are auto-created by the resource when Config.AutoCreateDatabase / AutoSeedDefaultZones are true.
-- Use this file only if you prefer a manual import.

CREATE TABLE IF NOT EXISTS `rsg_rocks_zones` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `x` DOUBLE NOT NULL,
  `y` DOUBLE NOT NULL,
  `z` DOUBLE NOT NULL,
  `radius` FLOAT NOT NULL DEFAULT 2.0,
  `heading` FLOAT NOT NULL DEFAULT 0.0,
  `ore_type` VARCHAR(32) NOT NULL DEFAULT 'rock',
  `label` VARCHAR(64) DEFAULT NULL,
  `enabled` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_enabled` (`enabled`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

